body { background: var(--bg); color: var(--fg); font-family: var(--body); font-size: 16px; line-height: 1.55; padding-inline: 16px; padding-block: 24px 64px; }
.page { max-width: 46rem; margin: 0 auto; display: flex; flex-direction: column; gap: 24px; }
